def average_kerry(samples: list[dict[str, float]]) -> float:
    totals = {name: 0.0 for name in set(s["candidate"] for s in samples)}

    for s in samples:
        totals[s["candidate"]] += s["percentage"]

    return totals["John Kerry"] / len(totals["John Kerry"]) if any(totals["John Kerry"]) else 0.0
```

